/* SystemMngMapperVE.selectCustomerCodeList : QnA 거래처 조회 */		
	SELECT CUSTOMER_CODE
	FROM TB_SMS_CUSTOMER 
	WHERE 1=1

		AND ENT_CODE = #{entCode}



			AND CUSTOMER_TYPE IN('HC','SC')
			AND (PARENT_CUSTOMER_CODE = #{ecmCustomerCode} OR CUSTOMER_CODE = #{ecmCustomerCode})


			AND CUSTOMER_TYPE = 'SC'
			AND CUSTOMER_CODE = #{ecmCustomerCode}

/* SystemMngMapperVE.selectQnAList : 문의사항(QnA) List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT T1.REFERENCE_NO , T1.ENT_CODE , T1.CUSTOMER_CODE , (SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = #{entCode} AND CUSTOMER_CODE = T1.CUSTOMER_CODE) AS CUSTOMER_NAME , T1.PO_NO , T1.HBL_NO , od.HBL_NO AS OD_HBL_NO , od.MULTI_DELIVERY_NO , ISNULL(T1.SEQ_NO_ID, 0) AS SEQ_NO_ID , T1.QUESTION_USER_TYPE , T1.QUESTION_TYPE , (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = T1.ENT_CODE AND GROUP_CODE = 'QUESTION_TYPE_VE' AND CODE = T1.QUESTION_TYPE) AS QUESTION_TYPE_NAME , T1.EMERGENCY_YN , CASE WHEN T1.COMPLETE_YNH = 'Y' THEN '답변완료' WHEN DT.QANDA_TYPE = 'A' THEN '답변확인요청' WHEN DT.QANDA_TYPE = 'Q' THEN '답변요청' ELSE '' END AS COMPLETE_YNH , CASE WHEN DT.QANDA_TYPE = 'A' THEN DT.UPDATE_DATE_TIME ELSE NULL END AS ANSWER_DATE_TIME , T1.HOLD_REASON , T1.TITLE , T1.CONTENTS , T1.REGISTER_USER_ID , T1.REGISTER_DATE_TIME , T1.UPDATE_USER_ID , T1.UPDATE_DATE_TIME , (SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = T1.ENT_CODE AND USER_ID = T1.REGISTER_USER_ID) AS REGISTER_USER_NAME , (SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = T1.ENT_CODE AND USER_ID = T1.UPDATE_USER_ID) AS UPDATE_USER_NAME
, CASE WHEN T1.QUESTION_USER_TYPE = 'C' THEN T1.CUSTOMER_CODE ELSE T1.REGISTER_USER_ID END QUESTION_USER_ID , DT1.ANSWER_USER_ID , CASE WHEN T1.QUESTION_USER_TYPE = 'C' THEN (SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = #{entCode} AND CUSTOMER_CODE = T1.CUSTOMER_CODE) ELSE (SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = T1.ENT_CODE AND USER_ID = T1.REGISTER_USER_ID) END QUESTION_USER_NAME , (SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = T1.ENT_CODE AND USER_ID = DT1.ANSWER_USER_ID) AS ANSWER_USER_NAME , OD.OD_JOB_NO , OD.CUST_CODE_LV1 , OD.CUST_CODE_LV2 , DT1.SLA , FS.REFERENCE_NO_ID AS FILE_REFERENCE_NO_ID , CASE WHEN FS.REFERENCE_NO_ID IS NOT NULL AND (LTRIM(RTRIM(T1.FILE_TEMP_NAME)) != '' OR LTRIM(RTRIM(DT1.FILE_TEMP_NAME)) != '') THEN 'Y' ELSE 'N' END AS FILE_SHARE , CONCAT((SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = T1.ENT_CODE AND GROUP_CODE = 'BOUND' AND CODE = OD.BOUND), (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = T1.ENT_CODE AND GROUP_CODE = 'BOUND_TYPE' AND CODE = OD.BOUND_TYPE)) AS BOUND FROM TB_ECM_QANDA T1 -- 최근 SEQ_NO를 먼저 찾고 LEFT JOIN LEFT JOIN ( SELECT D1.REFERENCE_NO, D1.QANDA_TYPE, D1.UPDATE_DATE_TIME FROM TB_ECM_QANDA_DETAIL D1 INNER JOIN ( SELECT REFERENCE_NO, MAX(SEQ_NO) AS MAX_SEQ_NO FROM TB_ECM_QANDA_DETAIL GROUP BY REFERENCE_NO ) AS Latest ON D1.REFERENCE_NO = Latest.REFERENCE_NO AND D1.SEQ_NO = Latest.MAX_SEQ_NO ) AS DT ON T1.REFERENCE_NO = DT.REFERENCE_NO
LEFT JOIN ( SELECT D1.REFERENCE_NO , MAX(CASE WHEN D1.QANDA_TYPE = 'Q' THEN D1.REGISTER_USER_ID END) AS QUESTION_USER_ID , MAX(CASE WHEN D1.QANDA_TYPE = 'A' THEN D1.REGISTER_USER_ID END) AS ANSWER_USER_ID , DATEDIFF(DAY, MAX(CASE WHEN D1.QANDA_TYPE = 'Q' THEN D1.REGISTER_DATE_TIME END), MAX(CASE WHEN D1.QANDA_TYPE = 'A' THEN D1.REGISTER_DATE_TIME END)) AS SLA , CAST(MIN(D1.SEQ_NO) AS VARCHAR) AS MIN_SEQ_NO , MAX(FILE_TEMP_NAME) AS FILE_TEMP_NAME FROM TB_ECM_QANDA_DETAIL D1 WHERE EXISTS ( SELECT 1 FROM (SELECT REFERENCE_NO, MAX(SEQ_NO) OVER(PARTITION BY REFERENCE_NO, QANDA_TYPE) AS SEQ_NO, FILE_TEMP_NAME FROM TB_ECM_QANDA_DETAIL) TEMP WHERE TEMP.REFERENCE_NO = D1.REFERENCE_NO AND TEMP.SEQ_NO = D1.SEQ_NO ) GROUP BY D1.REFERENCE_NO ) AS DT1 ON T1.REFERENCE_NO = DT1.REFERENCE_NO
LEFT OUTER JOIN (SELECT FUNC_JOB_NO, MAX(REFERENCE_NO_ID) AS REFERENCE_NO_ID FROM TB_COM_FILE_SHARE GROUP BY FUNC_JOB_NO) FS ON FS.FUNC_JOB_NO = T1.REFERENCE_NO
OUTER APPLY ( SELECT TOP 1 * FROM( SELECT od.OD_JOB_NO , od.CUST_CODE_LV1 , od.CUST_CODE_LV2 , od.PO_NO , CASE WHEN multi.OD_JOB_NO IS NULL THEN od.HBL_NO ELSE multi.DELIVERY_NO END AS BL_NO , od.HBL_NO , CASE WHEN multi.OD_JOB_NO IS NOT NULL THEN multi.DELIVERY_NO END AS MULTI_DELIVERY_NO , od.BOUND , od.BOUND_TYPE FROM TB_ECM_OD od WITH(NOLOCK) LEFT OUTER JOIN TB_ECM_OD_MULTI multi WITH(NOLOCK) ON multi.OD_JOB_NO = od.OD_JOB_NO) OD WHERE ISNULL(od.PO_NO,'') = ISNULL(T1.PO_NO,'') AND ISNULL(od.BL_NO,'') = ISNULL(T1.HBL_NO,'') ) AS OD
WHERE T1.ENT_CODE = #{entCode}
AND T1.${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND DT.${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND T1.${srchDateGbn} <= DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND DT.${srchDateGbn} <= DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND T1.PO_NO LIKE CONCAT('%',#{srchPoNo},'%')
AND T1.HBL_NO LIKE CONCAT('%',#{srchHblNo},'%')
AND T1.TITLE LIKE CONCAT('%',#{srchTitle},'%')
AND T1.QUESTION_TYPE = #{srchQuestionType}
AND T1.COMPLETE_YNH != 'Y' AND DT.QANDA_TYPE = #{srchCompleteYnh}
AND T1.COMPLETE_YNH = #{srchCompleteYnh}
AND (1 = 0 OR
(ISNULL(T1.COMPLETE_YNH,'') != 'Y' AND DT.QANDA_TYPE = #{item})
(ISNULL(T1.COMPLETE_YNH,'') != 'Y' AND DT.QANDA_TYPE = #{item})
ISNULL(T1.COMPLETE_YNH,'') = #{item}
)
AND T1.CUSTOMER_CODE IN
#{item}
AND OD.BOUND = #{srchBound}
AND OD.BOUND_TYPE = #{srchBoundType}

mapper.insert:
/* SystemMngMapperVE.insertQnA : 문의사항(QnA) Insert */

	SELECT 
		CONCAT(#{entCode},CONVERT(CHAR(6), GETDATE(), 112),'-',
			CONCAT(REPLICATE('0', 3 - LEN(A) ), A)
		)  AS REFERENCE_NO
	FROM 
	(SELECT 
		ISNULL((
				SELECT MAX(CEILING(SUBSTRING(REFERENCE_NO, 13, 3))) + 1 FROM TB_ECM_QANDA
				WHERE REFERENCE_NO LIKE CONCAT(#{entCode},CONVERT(CHAR(6), GETDATE(), 112),'%')								  
				), 1) AS A ) INFO


INSERT INTO TB_ECM_QANDA
(
	 REFERENCE_NO
	, ENT_CODE
	, CUSTOMER_CODE
	, CUSTOMER_NAME
	, PO_NO
	, HBL_NO
	, SEQ_NO_ID
	, QUESTION_USER_TYPE
	, QUESTION_TYPE
	, EMERGENCY_YN
	, COMPLETE_YNH
	, HOLD_REASON
	, TITLE
	, CONTENTS
	,FILE_CONTENT_TYPE
	,FILE_PATH
	,FILE_TEMP_NAME
	,FILE_ORIGINAL_NAME
	,REGISTER_USER_ID
	,REGISTER_DATE_TIME
	,UPDATE_USER_ID
	,UPDATE_DATE_TIME
)
VALUES
(
	 #{referenceNo}
	,#{entCode}
	,#{customerCode}
	,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = #{entCode} AND CUSTOMER_CODE = #{customerCode})
	,#{poNo}
	,#{hblNo}
	,#{seqNoId}
	,#{questionUserType}
	,#{questionType}
	,#{emergencyYn}
	,#{completeYnh}
	,#{holdReason}
	,#{title}
	,#{contents}
	,#{fileContentType}
	,#{filePath}
	,#{fileTempName}
	,#{fileOriginalName}
	,#{updateUserId}
	,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
	,#{updateUserId}
	,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
)	

INSERT INTO TB_ECM_QANDA_DETAIL
(
	 REFERENCE_NO
	, ENT_CODE
	, SEQ_NO
	, QANDA_TYPE
	, QUESTION_SEQ_NO
	, CONTENTS
	,FILE_CONTENT_TYPE
	,FILE_PATH
	,FILE_TEMP_NAME
	,FILE_ORIGINAL_NAME
	,REGISTER_USER_ID
	,REGISTER_DATE_TIME
	,UPDATE_USER_ID
	,UPDATE_DATE_TIME
)
VALUES
(
	 #{referenceNo}
	,#{entCode}
	,#{seqNo}


			,'A'


			,'Q'





			, #{questionSeqNo}


			, NULL


	,#{contents}
	,#{fileContentType}
	,#{filePath}
	,#{fileTempName}
	,#{fileOriginalName}
	,#{updateUserId}
	,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
	,#{updateUserId}
	,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
)

		/* SystemMngMapperVE.insertSubQnA : 문의사항(QnA) Insert */

        	SELECT ISNULL(MAX(SEQ_NO), 0) + 1 FROM TB_ECM_QANDA_DETAIL WHERE REFERENCE_NO = #{referenceNo}

		INSERT INTO TB_ECM_QANDA_DETAIL
		(
			 REFERENCE_NO
			, ENT_CODE
			, SEQ_NO
			, QANDA_TYPE
			, QUESTION_SEQ_NO
			, CONTENTS
			,FILE_CONTENT_TYPE
			,FILE_PATH
			,FILE_TEMP_NAME
			,FILE_ORIGINAL_NAME
			,REGISTER_USER_ID
			,REGISTER_DATE_TIME
			,UPDATE_USER_ID
			,UPDATE_DATE_TIME
		)
		VALUES
		(
			 #{referenceNo}
			,#{entCode}
			,#{seqNo}
			,#{qandaType}


					,NULL


					, #{questionSeqNo}


			,#{contents}
			,#{fileContentType}
			,#{filePath}
			,#{fileTempName}
			,#{fileOriginalName}
			,#{updateUserId}
			,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
			,#{updateUserId}
			,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
		)	



			UPDATE TB_ECM_QANDA SET 
					 COMPLETE_YNH = #{completeYnh}
					, HOLD_REASON = #{holdReason}
			WHERE ENT_CODE = #{entCode} 
			AND REFERENCE_NO = #{referenceNo}

