/* SystemMngMapperVE.selectQnADetail : 문의사항(QnA) Data */ SELECT TOP 1 T1.REFERENCE_NO , T1.ENT_CODE , T1.CUSTOMER_CODE , (SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = #{entCode} AND CUSTOMER_CODE = T1.CUSTOMER_CODE) AS CUSTOMER_NAME , T1.PO_NO , T1.HBL_NO , T1.QUESTION_TYPE , T1.EMERGENCY_YN , T1.COMPLETE_YNH , T1.HOLD_REASON , T1.TITLE , T1.CONTENTS , T1.FILE_CONTENT_TYPE , T1.FILE_PATH , T1.FILE_TEMP_NAME , T1.FILE_ORIGINAL_NAME
, D1.SEQ_NO , D1.QANDA_TYPE , D1.QUESTION_SEQ_NO , T1.REGISTER_USER_ID , T1.REGISTER_DATE_TIME , T1.UPDATE_USER_ID , T1.UPDATE_DATE_TIME , (SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = T1.ENT_CODE AND USER_ID = T1.REGISTER_USER_ID) AS REGISTER_USER_NAME , (SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = T1.ENT_CODE AND USER_ID = T1.UPDATE_USER_ID) AS UPDATE_USER_NAME
, (SELECT MAX(CUST_CODE_LV1) FROM TB_ECM_OD WHERE ENT_CODE = T1.ENT_CODE AND PO_NO = T1.PO_NO) AS CUST_CODE_LV1 , T1.QUESTION_USER_TYPE FROM TB_ECM_QANDA T1 LEFT JOIN TB_ECM_QANDA_DETAIL D1 ON T1.REFERENCE_NO = D1.REFERENCE_NO WHERE T1.ENT_CODE = #{entCode}
AND T1.CUSTOMER_CODE = #{customerCode}
AND T1.REFERENCE_NO = #{referenceNo}
AND D1.SEQ_NO = #{seqNo}
ORDER BY SEQ_NO DESC

