/* SystemMngMapperVE.insertCsHistory : 히스토리등록 */
INSERT INTO TB_ECM_OD_CS_HISTORY(
	OD_JOB_NO
	,OD_SEQ_NO_ID
	,CS_DATE
	,CS_TYPE
	,CS_REMARK
	,REGISTER_USER_ID
	,REGISTER_DATE_TIME
	,UPDATE_USER_ID
	,UPDATE_DATE_TIME
	,SEQ_NO_ID
)
VALUES(
	#{odJobNo}
	,#{seqNoId}
	,DATEADD(HOUR, ${gmtTime}, GETDATE())
	,#{questionType}
	,#{contents}
	,#{updateUserId}
	,DATEADD(HOUR, ${gmtTime}, GETDATE())
	,#{updateUserId}
	,DATEADD(HOUR, ${gmtTime}, GETDATE())
	,(SELECT ISNULL(MAX(SEQ_NO_ID), 0) + 1 FROM TB_ECM_OD_CS_HISTORY WHERE OD_JOB_NO = #{odJobNo} AND ISNULL(OD_SEQ_NO_ID, 0) = #{seqNoId})
)

mapper.select:
/* SystemMngMapperVE.selectQnAHistoryList : 문의사항(QnA) - 이력관리 */ SELECT ROW_NUMBER() OVER(ORDER BY CS.SEQ_NO_ID) AS NUM ,CS.CS_DATE ,CS.CS_TYPE ,ISNULL((SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{entCode} AND GROUP_CODE='QUESTION_TYPE_VE' AND CODE = CS.CS_TYPE), CS.CS_TYPE) AS CS_TYPE_NAME ,ISNULL(CS.CS_REMARK, '') AS CS_REMARK FROM TB_ECM_OD_CS_HISTORY CS JOIN TB_ECM_OD OD ON CS.OD_JOB_NO = OD.OD_JOB_NO WHERE 1 = 1
AND OD.PO_NO = #{srchNo}
AND OD.HBL_NO = #{srchNo}
AND CS.OD_JOB_NO = #{srchOdJobNo}
AND ISNULL(CS.OD_SEQ_NO_ID, 0) = #{seqNo}
ORDER BY CS.SEQ_NO_ID

mapper.insert:
	/* SystemMngMapperVE.insertQnafileShare : 파일등록 */

	SELECT ISNULL(MAX(REFERENCE_NO_ID), 0) + 1 
  	FROM TB_COM_FILE_SHARE


	INSERT INTO TB_COM_FILE_SHARE(			
		REFERENCE_NO_ID
		,ENT_CODE
		,ENT_BUSINESS_CODE
		,SOLUTION
		,FUNC_TYPE
		,FUNC_SUB_TYPE
		,FUNC_JOB_NO
		,FUNC_REFERENCE_NO
		,FILE_DOC_TYPE
		,FILE_NAME
		,FILE_EXT
		,FILE_SIZE
		,FILE_NAME_REMOTE
		,FILE_PATH_REMOTE
		,SHARE_YN
		,MEMO_DATE
		,FS_SERVER_TYPE
		,REGISTER_USER_ID
