WHERE OD_JOB_NO = #{odJobNo}

mapper.update:
/* SystemMngMapperVE.updateOrderReturnInfo : 오더 반품 처리 */
UPDATE TB_ECM_OD SET
	RETURN_YN = 'Y'
WHERE OD_JOB_NO = #{odJobNo};

UPDATE TB_ECM_OD_ADDITIONAL SET
	RETURN_REQ_DATE = GETDATE()
	,RETURN_REQUEST_ID = #{updateUserId}
WHERE OD_JOB_NO = #{odJobNo};

		/* SystemMngMapperVE.insertMultiInfo : 멀티송장처리 */
		UPDATE TB_ECM_OD_MULTI
		SET 
			UPDATE_USER_ID = #{updateUserId}
			,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())

			,DELIVERY_CODE = #{deliveryCode}


			,DELIVERY_NO_CHANGED = #{deliveryNoChanged}



				,RETURN_DELIVERY_CODE = #{returnDeliveryCode}

			,RETURN_REQ_DATE = GETDATE()

		WHERE OD_JOB_NO = #{odJobNo}
		AND ISNULL(SEQ_NO_ID, 0) = #{seqNoId}
		;

    	IF @@ROWCOUNT = 0

    	INSERT INTO TB_ECM_OD_MULTI(
			OD_JOB_NO
			,SEQ_NO_ID
			,DELIVERY_NO
			,DELIVERY_CODE
			,DELIVERY_NO_CHANGED
			,PIECES

			,RETURN_DELIVERY_CODE
			,RETURN_REQ_DATE

			,REGISTER_USER_ID
			,REGISTER_DATE_TIME
		)VALUES(
			#{odJobNo}
			,(SELECT ISNULL(MAX(SEQ_NO_ID),0) + 1 FROM TB_ECM_OD_MULTI WHERE OD_JOB_NO = #{odJobNo})
			,#{deliveryNo}
			,#{deliveryCode}
			,#{deliveryNoChanged}
			,#{pieces}

			,#{returnDeliveryCode}
			,GETDATE()

			,#{updateUserId}
			,DATEADD(HOUR, ${gmtTime}, GETDATE())
		)

